violating:
import { Config, Effect, Schema as S, pipe } from "effect"

const parallelRenders = Config.Number("RENDER_PARALLELISM")

const retryLimit = pipe(
  "RENDER_RETRY_LIMIT",
  Config.schema(S.Int.check(S.isGreaterThanOrEqualTo(0)))
)

const flushIntervalSeconds = pipe(
  "RENDER_FLUSH_INTERVAL_SECONDS",
  Config.schema(S.Finite.check(S.isGreaterThan(0)))
)

export const rendererConfig = Effect.gen(function*() {
  const parallelism = yield* parallelRenders
  if (!Number.isInteger(parallelism) || parallelism <= 0) {
    return yield* Effect.fail(
      new Error("RENDER_PARALLELISM must be a positive integer")
    )
  }

  const retries = yield* retryLimit
  const flushSeconds = yield* flushIntervalSeconds

  return {
    parallelism,
    retries,
    flushSeconds
  }
})

